function parseThresholds(thresholdStrings: string[] | undefined): Record<string, number> {
  const thresholds: Record<string, number> = {};
  if (!thresholdStrings) return thresholds;

  for (const thresholdStr of thresholdStrings) {
    const match = thresholdStr.match(/^([a-z_]+)=([0-9.]+)$/);
    if (!match) {
      log.error(`Malformed threshold: '${thresholdStr}'. Expected format: <metric>=<number>`);
      process.exit(2);
    }
    const [, metric, valueStr] = match;
    const value = parseFloat(valueStr);
    if (isNaN(value) || value < 0 || value > 1) {
      log.error(`Invalid threshold for '${metric}': minimum must be a number between 0 and 1, got ${valueStr}`);
      process.exit(2);
    }
    thresholds[metric] = value;
  }

  return thresholds;
}

function runEvalCommand(options: EvalOptions) {
  assertFileExists(options.outputs);
  const dataset = (Eval.loadDataset as unknown as (config: unknown) => any)({
    outputsPath: options.outputs,
    referencesPath: options.references
  });
  const evaluations = (Eval.runEvaluations as unknown as (config: unknown) => any)({
    outputs: dataset.outputs,
    references: dataset.references
  });

  const thresholds = parseThresholds(options.threshold);

  // Validate thresholds against available metrics
  if (Object.keys(thresholds).length > 0) {
    const validateThresholds = (Eval.validateThresholds as unknown as (thresholds: unknown, metrics: unknown) => string[])({}, evaluations);
    const errors = (Eval.validateThresholds as unknown as (thresholds: unknown, metrics: unknown) => string[])(thresholds, evaluations);
    if (errors.length > 0) {
      errors.forEach((error) => log.error(error));
      process.exit(2);
    }
  }

  const report = (Eval.generateReport as unknown as (config: unknown) => any)({
    evaluations,
    outputsPath: dataset.outputsPath,
    referencesPath: dataset.referencesPath,

