export function generateReport({
  evaluations,
  outputsPath,
  referencesPath,
  thresholds = {},
  generatedAt = new Date().toISOString()
}) {
  const totalSamples = evaluations.reduce((total, metric) => {
    if (typeof metric.total === 'number') return Math.max(total, metric.total);
    return total;
  }, 0);

  const thresholdResults = evaluateThresholds(thresholds, evaluations);
  const passed = thresholdResults.length === 0 || thresholdResults.every((t) => t.passed);

  return {
    metadata: {
      generatedAt,
      outputsPath,
      referencesPath,
      totalSamples
    },
    metrics: evaluations,
    ...(Object.keys(thresholds).length > 0 && {
      passed,
      thresholds: thresholdResults
    })
  };
}
